// Cross-check: every pattern generated by the browser engine and by the Python code (numbers exported from
// /api/check), compared command count, colour indices, coordinate sum and extent.
import { route, app, api, esc, list } from './core.js';
import { generate, stats } from './engine.js';

const rel = (a, b) => Math.abs(a - b) / Math.max(1, Math.abs(b));
const CHAOTIC = 'Strange Attractors';

route('check', async () => {
  const data = await api('/check');
  app().innerHTML = `<p class="kicker">Cross-check</p><h1 class="glow">Browser engine vs Python</h1>
  <p class="lead">Each pattern is generated here by the JS port and compared with the numbers the Python generators
  produced (<code>/api/check</code>, computed when the site was built) at ${data.cases[0].width} x ${data.cases[0].height} px with
  default parameters${Object.keys(data.overrides).length ? ` (except ${list(Object.entries(data.overrides), ([n, o]) => `${esc(n)}: ${esc(JSON.stringify(o))}`, ', ')}, to keep the Python export quick)` : ''}.</p>
  <p>The seeded patterns use a port of Python's Mersenne Twister, so random tiles, points and seeds are identical too. The
  node tests in the repository go further: 68 parameter sets covering every mode, sampled command by command, and every
  post-processing effect pixel by pixel against Pillow.</p>
  <div class="scroll"><table class="check"><tr><th>Pattern</th><th>Commands (Python)</th><th>Commands (JS)</th>
    <th>Coordinate sum, relative difference</th><th>Colour indices</th><th>Result</th></tr><tbody id="rows"></tbody></table></div>
  <p class="callout small">Strange attractors are chaotic: a difference in the last bit of sin or cos between Python's
  maths library and the browser's grows until the two orbits part after a few dozen steps, although both trace the same
  attractor. For them the check compares the count, colour indices and the extent of the drawing (within 5%).</p>`;
  const rows = document.getElementById('rows');
  let ok = 0;
  for (const c of data.cases) {
    await new Promise(r => setTimeout(r, 0));
    const s = stats(generate(c.name, c.width, c.height, c.params)), py = c.stats;
    const cols = JSON.stringify(Object.entries(s.colors).map(([k, v]) => [String(k), v]).sort()) ===
      JSON.stringify(Object.entries(py.colors).sort());
    const d = rel(s.sum, py.sum);
    const box = s.bbox && py.bbox ? Math.max(...s.bbox.map((v, j) => rel(v, py.bbox[j]))) : 0;
    const pass = s.count === py.count && cols && (c.name === CHAOTIC ? box < 0.05 : d < 1e-9);
    ok += pass;
    rows.insertAdjacentHTML('beforeend', `<tr><td><a href="#/studio?p=${c.slug}">${esc(c.name)}</a></td>
      <td class="num">${py.count.toLocaleString('en')}</td><td class="num">${s.count.toLocaleString('en')}</td>
      <td class="num">${c.name === CHAOTIC ? `extent ${box.toExponential(1)}` : d.toExponential(1)}</td>
      <td>${cols ? 'same' : 'differ'}</td><td class="${pass ? 'okc' : 'badc'}">${pass ? 'match' : 'MISMATCH'}</td></tr>`);
  }
  rows.insertAdjacentHTML('beforeend', `<tr><td colspan="6"><b>${ok} of ${data.cases.length} patterns match.</b></td></tr>`);
});
